<template>
  <div class="sg-client-page sg3-utility-page"><PublicNavbar /><main class="sg3-container sg3-profile-main"><div class="sg3-page-head"><div><div class="sg3-breadcrumbs"><router-link to="/profile">Tài khoản</router-link><span>/</span><strong>Hoàn tiền</strong></div><p class="sg3-kicker">Tài chính cá nhân</p><h1>Yêu cầu hoàn tiền</h1><p>Theo dõi trạng thái và số tiền hoàn từ các booking của bạn.</p></div><router-link class="sg3-button sg3-button--primary" to="/bookings"><AppIcon name="calendar" :size="16" />Lịch đặt sân</router-link></div><section v-if="loading" class="sg3-empty"><div><strong>Đang tải yêu cầu hoàn</strong><p>Đang đồng bộ trạng thái xử lý.</p></div></section><section v-else-if="error" class="sg3-error"><div><strong>Không tải được yêu cầu hoàn</strong><p>{{ error }}</p><button class="sg3-button sg3-button--primary" type="button" @click="load">Thử lại</button></div></section><section v-else class="sg3-card sg3-request-card"><header><strong>{{ total }} yêu cầu</strong><button class="sg3-button sg3-button--quiet" type="button" @click="load">Làm mới</button></header><div v-if="!refunds.length" class="sg3-empty sg3-empty--inline"><div><strong>Chưa có yêu cầu hoàn tiền</strong><p>Những khoản hoàn từ booking sẽ được theo dõi tại đây.</p><router-link class="sg3-button sg3-button--secondary" to="/bookings">Xem lịch đặt</router-link></div></div><article v-for="refund in refunds" :key="refund.id" class="sg3-request-row"><div><strong>{{ refund.booking?.booking_code || refund.booking?.code || `Yêu cầu #${refund.id}` }}</strong><span>{{ refund.booking?.venue_cluster?.name || refund.booking?.venueCluster?.name || "Booking SportGo" }}</span><small>{{ formatDate(refund.created_at) }}</small></div><div class="sg3-request-amount"><strong>{{ money(refund.refund_amount ?? refund.amount) }}</strong><span class="sg3-status-pill" :class="statusClass(refund.status)">{{ statusLabel(refund.status) }}</span></div><router-link :to="{name:'client-refund-detail',params:{id:refund.id}}" aria-label="Xem chi tiết"><AppIcon name="chevronRight" :size="18" /></router-link></article><footer v-if="lastPage>1" class="sg3-pagination"><button class="sg3-button sg3-button--secondary" type="button" :disabled="page<=1" @click="goPage(page-1)">Trước</button><span>Trang {{ page }} / {{ lastPage }}</span><button class="sg3-button sg3-button--secondary" type="button" :disabled="page>=lastPage" @click="goPage(page+1)">Sau</button></footer></section></main></div>
</template>
<script>
import AppIcon from "../../components/AppIcon.vue";import PublicNavbar from "../../components/PublicNavbar.vue";import { bookingService } from "../../services/bookingService.js";
export default {name:"ClientRefunds",components:{AppIcon,PublicNavbar},data(){return{refunds:[],page:1,lastPage:1,total:0,loading:true,error:""};},mounted(){this.load();},methods:{async load(){this.loading=true;this.error="";try{const response=await bookingService.listRefunds({page:this.page});this.refunds=response.data||[];this.page=Number(response.current_page||this.page);this.lastPage=Number(response.last_page||1);this.total=Number(response.total||this.refunds.length);}catch(error){this.error=error.message||"Vui lòng thử lại.";}finally{this.loading=false;}},goPage(page){this.page=page;this.load();},money(value){return new Intl.NumberFormat("vi-VN",{style:"currency",currency:"VND",maximumFractionDigits:0}).format(Number(value||0));},formatDate(value){return value?new Date(value).toLocaleString("vi-VN"):"-";},statusLabel(status){return{pending:"Đang xử lý",approved:"Đã duyệt",processing:"Đang hoàn",completed:"Đã hoàn",rejected:"Từ chối",cancelled:"Đã hủy"}[status]||status||"Chưa cập nhật";},statusClass(status){return`status-${status||"pending"}`;}}};
</script>
